'use strict';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={articles:[],documents:[]};let favorites=read('arb-favorites',[]),history=read('arb-history',[]);function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Не удалось сохранить данные в браузере')}}function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}
function get(id){return [...data.articles,...data.documents].find(x=>x.id===id)}function fav(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];write('arb-favorites',favorites);renderAll()}function remember(id){history=[id,...history.filter(x=>x!==id)].slice(0,10);write('arb-history',history);renderSaved()}function favButton(id){return `<button data-fav="${esc(id)}" aria-pressed="${favorites.includes(id)}">${favorites.includes(id)?'★ В избранном':'☆ В избранное'}</button>`}
function article(a){let details=a.number?`<p><b>Статья ${esc(a.number)} УК РО:</b> ${esc(a.official)}.</p><p><b>Наказание:</b> ${esc(a.punishment)}</p>`:'';return `<article class="card" id="article-${esc(a.id)}"><div class="card-top"><span class="code">${a.number?'УК РО / СТ. '+esc(a.number):'ТЕМА / БЕЗ НОМЕРА'}</span><span class="badge">${esc(a.status)}</span></div><h3>${esc(a.title)}</h3><p>${a.number?'Условия применения и санкции зависят от части статьи.':'Норма не установлена: проверьте первоисточник.'}</p><details><summary>Подробнее</summary><div class="detail">${details}<p><b>Условия:</b> ${esc(a.conditions)}</p><p>Проверено: ${esc(a.checked)}. Сверяйте изменения в теме форума.</p><div class="actions">${favButton(a.id)}<button data-copy="${esc(a.id)}">Копировать</button><a data-open="${esc(a.id)}" href="${esc(a.url)}" target="_blank" rel="noopener">Первоисточник ↗</a></div></div></details></article>`}
function doc(d){return `<article class="doc" id="doc-${esc(d.id)}"><div class="doc-cat">${esc(d.category.toUpperCase())}</div><div><h3>${esc(d.title)}</h3><p>${esc(d.summary)}</p><div class="meta">${esc(d.status)} · проверка каталога ${esc(d.checked)} · тема опубликована ${esc(d.published)}</div></div><div class="actions">${favButton(d.id)}<a data-open="${esc(d.id)}" href="${esc(d.url)}" target="_blank" rel="noopener">Открыть ↗</a></div></article>`}
function renderDocs(){let f=$('#doc-filter').value;$('#documents-list').innerHTML=data.documents.filter(d=>f==='all'||d.category===f).map(doc).join('')||'<p class="empty">Данные ещё не добавлены.</p>'}function renderArticles(){$('#articles-list').innerHTML=data.articles.map(article).join('')}
function renderSaved(){$('#fav-count').textContent=favorites.length;for(let [sel,ids,msg] of [['#favorites',favorites,'Пока ничего не сохранено.'],['#history',history,'Открытые материалы появятся здесь.']]){$(sel).innerHTML=ids.map(id=>get(id)).filter(Boolean).map(x=>`<a class="saved-item" href="#${x.number||x.id.startsWith('t')?'article-':'doc-'}${esc(x.id)}">${esc(x.title)} →</a>`).join('')||`<p class="empty">${msg}</p>`}}
function highlight(s,q){let safe=esc(s), term=esc(q.trim());if(!term)return safe;let regex=new RegExp(term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'ig');return safe.replace(regex,m=>`<mark>${m}</mark>`)}function search(){let q=$('#search').value.trim().toLocaleLowerCase('ru'),f=$('#search-filter').value;$('#search-results').classList.toggle('hidden',!q);if(!q)return;let entries=[...data.articles.map(x=>({...x,kind:'Статьи'})),...(window.ukIndex||[]).map(x=>({...x,id:'uk-'+x.number,kind:'Статьи',indexOnly:true,document:'Уголовный кодекс РО',status:'Оглавление · полный текст на форуме'})),...data.documents.map(x=>({...x,kind:x.category}))].filter(x=>(f==='all'||x.kind===f)&&[x.title,x.number,x.official,x.punishment,x.conditions,x.keywords,x.document,x.summary,x.category].filter(Boolean).join(' ').toLocaleLowerCase('ru').includes(q));$('#results').innerHTML=entries.map(x=>`<div class="search-result"><a href="#${x.indexOnly?'':x.kind==='Статьи'?'article-':'doc-'}${esc(x.id)}">${highlight(x.title,q)} ${x.number?'· ст. '+highlight(x.number,q):''} →</a><p>${esc(x.document||x.category)} · ${esc(x.status)}</p><p>${highlight(x.conditions||x.summary||'',q)}</p></div>`).join('')||'<p class="empty">Ничего не найдено. Попробуйте другой запрос или фильтр. Некоторые данные ещё не добавлены.</p>'}
function renderAll(){renderArticles();renderDocs();renderSaved();search()}function output(){let v=id=>$('#'+id).value.trim()||({'officer':'[имя сотрудника]','position':'[должность]','reason':'[причина]','law':'[пункт, часть, статья]','person':'[имя задержанного]','receiver':'[принимающий сотрудник]'}[id]);let reason=`Вы задержаны по подозрению: ${v('reason')}. Основание: ${v('law')}.`,rights='Вы имеете право на защиту и можете вызвать адвоката. По вашей просьбе указанная статья будет разъяснена полностью.';let t={short:`${reason} ${rights}`,standard:`${v('position')} ${v('officer')}. ${v('person')}, ${reason} ${rights}`,official:`Я, ${v('position')} ${v('officer')}, сообщаю: ${v('person')}, ${reason} ${rights} Дальнейшие действия проводятся в установленном порядке.`,reason:`Причина задержания: ${v('reason')}. Предполагаемая норма: ${v('law')}.`,rights,refusal:`${v('person')}, прошу выполнить законное требование сотрудника. Причина обращения: ${v('reason')}.`,transfer:`Сотруднику ${v('receiver')} передаётся задержанный ${v('person')}. Основание: ${v('reason')}; ${v('law')}. Передал: ${v('position')} ${v('officer')}.`};$('#output').textContent=t[$('#template').value]}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Текст скопирован')}catch{let el=document.createElement('textarea');el.value=s;document.body.appendChild(el);el.select();try{document.execCommand('copy')?toast('Текст скопирован'):toast('Не удалось скопировать текст')}catch{toast('Не удалось скопировать текст')}el.remove()}}
document.addEventListener('click',e=>{let local=e.target.closest('a[href^="#article-"],a[href^="#doc-"]');if(local){let id=local.getAttribute('href').replace(/^#(?:article|doc)-/,'');if(get(id)){if(id.startsWith('a')||id.startsWith('t')){let item=document.getElementById('article-'+id);if(item)item.querySelector('details').open=true}else if(!document.getElementById('doc-'+id)){$('#doc-filter').value='all';renderDocs()}remember(id)}}let b=e.target.closest('[data-fav]');if(b){fav(b.dataset.fav);return}b=e.target.closest('[data-copy]');if(b){let x=get(b.dataset.copy);copy(`${x.title}${x.number?' — ст. '+x.number+' УК РО':''}\n${x.punishment}\n${x.conditions}\nИсточник: ${x.url}`);return}b=e.target.closest('[data-open]');if(b)remember(b.dataset.open);b=e.target.closest('[data-query]');if(b){$('#search').value=b.dataset.query;search();$('#search-results').scrollIntoView({behavior:'smooth'})}if(e.target.closest('#nav a')){$('#nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')}b=e.target.closest('[data-answer]');if(b){$('#quiz-result').textContent=b.dataset.answer==='right'?'Верно. Статья 92 УПК предусматривает разъяснение причины, нормы и права на защиту; предусмотрены и другие условия.':'Не совсем. Проверьте пункт «г» части 1 статьи 92 УПК РО.'}});
$('.menu').onclick=()=>{let open=$('#nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(open))};$('#search').addEventListener('input',search);$('#search-filter').onchange=search;$('#doc-filter').onchange=renderDocs;$('#clear-search').onclick=()=>{$('#search').value='';search();$('#search').focus()};$('#clear-history').onclick=()=>{history=[];write('arb-history',history);renderSaved()};$('#copy-template').onclick=()=>copy($('#output').textContent);for(let id of ['template','officer','position','reason','law','person','receiver'])$('#'+id).addEventListener('input',output);output();
fetch('./data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(x=>{data=x;renderAll();if(location.hash){let el=document.getElementById(location.hash.slice(1));if(el)el.scrollIntoView()}}).catch(()=>{$('#documents-list').innerHTML='<p class="empty">Не удалось загрузить базу. Откройте сайт через веб-сервер и проверьте data.json.</p>';$('#articles-list').innerHTML='<p class="empty">Данные ещё не добавлены или недоступны.</p>'});
